from pathlib import Path
import nbformat as nbf
R=Path(__file__).resolve().parents[2]; nb=nbf.v4.new_notebook(); nb.metadata={'kernelspec':{'display_name':'jup-venv','language':'python','name':'jup-venv'},'language_info':{'name':'python','version':'3.11'},'phase':12,'display_only':True,'cache_backed':True}
def md(s): return nbf.v4.new_markdown_cell(s)
def code(s): return nbf.v4.new_code_cell(s)
nb.cells=[md('# Phase 12 — KUB Oracle ROI / Zoom Upper-Bound Study\n\n**Oracle upper-bound; not deployable.** GT masks define component crop coordinates on KUB FULL_FIELD VAL only. GT pixels are never model input. The frozen UNet++ checkpoint and threshold 0.5 are unchanged. TEST and external data were not accessed.'),code("from pathlib import Path\nimport json,pandas as pd\nfrom IPython.display import display,Image\nROOT=Path.cwd().resolve(); ROOT=ROOT.parent if ROOT.name=='notebooks' else ROOT\nT=ROOT/'reports/tables'; F=ROOT/'reports/figures/phase12_oracle_roi'; Q=ROOT/'reports/qualitative/phase12_oracle_roi'; C=ROOT/'data_cache/phase12_oracle_roi'\nper_image=pd.read_csv(T/'phase12_oracle_roi_per_image.csv'); per_component=pd.read_csv(T/'phase12_oracle_roi_per_component.csv'); geometry=pd.read_csv(T/'phase12_oracle_crop_geometry.csv'); summary=pd.read_csv(T/'phase12_oracle_roi_summary.csv')\nassert len(per_image)==106 and len(per_component)==156 and len(geometry)==156\nprint('Governance PASS: phase4_v2; FULL_FIELD VAL only; TEST NOT ACCESSED; cache-backed; no training')"),md('## Phase-11 motivation and Oracle definition\n\nOne GT-guided original-space square crop per component is resized to 512×512. Frozen UNet++ predicts from the **one-channel image crop only**. Restored component probabilities are fused by pixelwise MAX, followed by the fixed 0.5 threshold. Margins 10%, 25% (primary), and 50% were predeclared.'),md('## Reproducible crop geometry and example'),code("display(geometry.head())\nprint('Median primary-margin effective magnification:',geometry.mag_25.median())"),md('## Global baseline and Oracle margin sensitivity'),code("display(summary)\ndisplay(Image(filename=str(F/'phase12_margin_sensitivity.png'),width=850))"),md('## Paired FULL_FIELD Dice effect'),code("d=per_image.dice_delta_oracle25_minus_global\ndisplay(pd.DataFrame({'mean':[d.mean()],'median':[d.median()],'Q1':[d.quantile(.25)],'Q3':[d.quantile(.75)],'improved':[(d>0).sum()],'unchanged':[(d==0).sum()],'worsened':[(d<0).sum()]}))\ndisplay(Image(filename=str(F/'phase12_global_vs_oracle_dice.png'),width=750))\ndisplay(Image(filename=str(F/'phase12_dice_delta_distribution.png'),width=850))"),md('## Original-space size recovery and TINY endpoint'),code("size=pd.read_csv(T/'phase12_oracle_roi_size_recovery.csv'); display(size)\ndisplay(Image(filename=str(F/'phase12_size_recall_global_vs_oracle.png'),width=850))\ndisplay(Image(filename=str(F/'phase12_tiny_recovery.png'),width=750))"),md('## Multi-component and empty-prediction recovery'),code("display(pd.read_csv(T/'phase12_oracle_roi_multicomponent.csv'))\ndisplay(Image(filename=str(F/'phase12_multicomponent_recovery.png'),width=850))\ndisplay(per_image[per_image.global_empty_prediction][['sample_id','global_dice','oracle25_dice','oracle25_empty_prediction']])\ndisplay(Image(filename=str(F/'phase12_empty_prediction_recovery.png'),width=650))"),md('## Effective image-space magnification'),code("display(geometry.groupby('kub_size_v1_stratum').mag_25.describe())\ndisplay(Image(filename=str(F/'phase12_magnification_vs_recovery.png'),width=850))"),md('## Deterministic Global-vs-Oracle panel'),code("display(Image(filename=str(Q/'phase12_global_vs_oracle_panel.png'),width=1300))"),md('## Limitations and FP caveat\n\nOracle ROI is artificially advantaged: GT constrains inference regions, so Oracle-constrained FP metrics are not fairly comparable to deployable global inference. This is a localization/resolution upper bound, not a clinical method. Results use one VAL split and one frozen model; no significance or causal superiority claim is made.'),md('## Phase-13 implication\n\nThe observed gain motivates development and evaluation of predicted ROI proposals. It does **not** prove that a deployable regional method will reproduce the Oracle gain. **Phase 13 was not executed. TEST NOT ACCESSED. STOP.**')]
out=R/'notebooks/10_kub_oracle_roi_upper_bound.ipynb'; out.write_text(nbf.writes(nb),encoding='utf-8'); print(out)
